table inet adaptive_trust_ci_webhook_bridge {
	chain input {
		type filter hook input priority filter - 10; policy accept;
		ip daddr 10.200.200.1 tcp dport 18080 iifname != "veth-vpn-h" counter packets 0 bytes 0 drop comment "bridge_wrong_interface"
		ip daddr 10.200.200.1 tcp dport 18080 ip saddr != 10.200.200.2 counter packets 0 bytes 0 drop comment "bridge_wrong_source"
		ip daddr 10.200.200.1 tcp dport 18080 iifname "veth-vpn-h" ip saddr 10.200.200.2 counter packets 0 bytes 0 accept comment "bridge_allowed_peer"
	}
}
